<!doctype html><html lang="es"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#171713;font-size:11px}h1{font-size:20px;margin-bottom:4px}.meta{color:#666;margin-bottom:18px}table{border-collapse:collapse;width:100%}th,td{border-bottom:1px solid #ddd;padding:7px;text-align:left}th{background:#f6c90e;font-size:9px;text-transform:uppercase}.num{text-align:right}</style></head><body><h1>Inventario - {{ $selectedBranch->name }}</h1><div class="meta">TIENDA IMPORTACIONES LIUVA · Generado {{ now()->format('d/m/Y H:i') }} · {{ $inventory->count() }} productos</div><table><thead><tr><th>Categoría</th><th>Producto</th><th class="num">Cantidad</th><th class="num">Precio</th></tr></thead><tbody>@foreach($inventory->sortBy(fn($x)=>$x->product->name) as $row)<tr><td>{{ $row->product->category?->name }}</td><td>{{ $row->product->name }}</td><td class="num">{{ $row->quantity }}</td><td class="num">S/ {{ number_format($row->product->sale_price,2) }}</td></tr>@endforeach</tbody></table></body></html>
